'use client'

import * as React from 'react'

// `./progress-bar` and `./segments` rather than `../<name>/<name>`: see the
// note in ./progress-bar.ts. The installed layout is flat, so these are the
// paths that are correct for a consumer, and the shims make them correct here.
import { ProgressBar } from './progress-bar'
import { Segments, type Segment } from './segments'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Quest, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './quest.css'

/**
 * Quest: a named task with a reward on it and a way of reading how far through
 * it the player is.
 *
 * Specimen 3c. "Daily: predict 3 races", a "+500" reward, and three segments
 * with two filled.
 *
 * A quest is measured one of two ways and the design draws one of them, so both
 * are here and neither is a second component. A quest counted in discrete
 * things done ("predict 3 races") renders `segments`, the same row of cells the
 * round indicator and the story pager use. A quest counted in a continuous
 * number ("earn 500 points") renders `progress-bar`. Pass `steps` for the first
 * and `value` with `max` for the second. BDS-022 makes `progress-bar` the base
 * for this component, and `segments` is what stops a third bar existing.
 *
 * There is no `data-gs-progress` and no `data-gs-fill`. How far through the
 * quest is, is `data-gs-value` over `data-gs-max`, and the nested component
 * carries the same pair, because it is the same number.
 *
 * It performs nothing. It does not count what the player did, award the
 * reward, or decide the quest is finished. The host says so.
 */

export interface QuestProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children' | 'title'> {
  /** What the quest asks for. The design's "Daily: predict 3 races". */
  title: string
  /** The supporting line under it, if the quest needs one. */
  detail?: string
  /** What is on offer, rendered as a pill. The design's "+500". */
  reward?: string
  /** The host's own id for that reward. Rides on `data-gs-reward`. */
  rewardId?: string
  /**
   * The discrete things the quest asks for, in order. Pass this for a quest
   * counted in steps, which is what the design draws.
   */
  steps?: Segment[]
  /** How far through a continuous quest. Pass with `max`, instead of `steps`. */
  value?: number
  /** The ceiling a continuous quest counts toward. */
  max?: number
  /** Finished. The host decides; the component never infers it from the number. */
  complete?: boolean
  /** Available later, not now. Keeps its shape and shows a padlock. */
  locked?: boolean
}

/** From the contract's table of state words, so no component invents its own. */
const STATE_WORD = {
  complete: 'complete',
  locked: 'locked',
} as const

/**
 * Inline SVG taking `currentColor`, never an emoji: an emoji carries its own
 * palette, ignores the theme and renders differently on every platform.
 */
function Padlock() {
  return (
    <svg viewBox="0 0 12 12" width="1em" height="1em" fill="none" aria-hidden="true" focusable="false">
      <rect x="2.5" y="5.5" width="7" height="5" rx="1" stroke="currentColor" strokeWidth="1.4" />
      <path d="M4.25 5.5V4a1.75 1.75 0 0 1 3.5 0v1.5" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" />
    </svg>
  )
}

function Tick() {
  return (
    <svg viewBox="0 0 12 12" width="1em" height="1em" fill="none" aria-hidden="true" focusable="false">
      <path d="M2.5 6.5 5 9l4.5-6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

export function Quest({
  title,
  detail,
  reward,
  rewardId,
  steps,
  value,
  max,
  complete = false,
  locked = false,
  className,
  ...rest
}: QuestProps) {
  // A stepped quest counts the steps behind the player; a continuous one takes
  // the number the host passed. Either way the root carries one value over one
  // max, which is what makes the two shapes one component rather than two.
  const stepped = steps !== undefined
  const countedValue = stepped ? steps.filter((s) => s.state === 'complete' || s.state === 'wrong').length : value
  const countedMax = stepped ? steps.length : max

  // The name carries the state, because a screen reader user gets no fill, no
  // pill and no padlock. Order: what it is, then where it is, then what is true.
  const words = [title]
  if (detail) words.push(detail)
  if (countedValue !== undefined && countedMax !== undefined) words.push(`${countedValue} of ${countedMax}`)
  if (reward) words.push(`reward ${reward}`)
  if (complete) words.push(STATE_WORD.complete)
  if (locked) words.push(STATE_WORD.locked)

  return (
    <div
      {...rest}
      className={['gs-quest', className].filter(Boolean).join(' ')}
      data-gs-component="quest"
      data-gs-value={countedValue}
      data-gs-max={countedMax}
      data-gs-complete={complete ? 'true' : undefined}
      data-gs-locked={locked ? 'true' : undefined}
      role="group"
      aria-label={words.join(', ')}
    >
      {/* aria-hidden throughout: the group's label above is the accessible
          name, and announcing the pieces again would read the quest twice. */}
      <span className="gs-quest__title" data-gs-scope="quest" data-gs-part="label" aria-hidden="true">
        {title}
      </span>

      {reward ? (
        <span
          className="gs-quest__reward"
          data-gs-scope="quest" data-gs-part="reward"
          // Rule 5 of the part vocabulary: a word may be both a part and an
          // attribute when the part is the element that renders that
          // attribute's value. This is that element.
          data-gs-reward={rewardId ?? reward}
          aria-hidden="true"
        >
          {reward}
        </span>
      ) : null}

      {detail ? (
        <span className="gs-quest__detail" data-gs-scope="quest" data-gs-part="detail" aria-hidden="true">
          {detail}
        </span>
      ) : null}

      <div className="gs-quest__progress">
        {/* One row of cells or one bar, never both, and never a third thing
            written here. Each keeps its own root marker, per the nesting rule,
            so a test can tell which shape rendered. */}
        {stepped ? (
          <Segments segments={steps} presentation="bar" label={title} showSummary aria-hidden="true" />
        ) : (
          <ProgressBar value={value} max={max} label={title} complete={complete} aria-hidden="true" />
        )}
      </div>

      {complete || locked ? (
        <span
          className="gs-quest__glyph"
          data-gs-scope="quest" data-gs-part="glyph"
          // Emphasis, not motion: the mark is what a reduced-motion player
          // reads instead of the fill travelling.
          data-gs-animates="emphasis"
          aria-hidden="true"
        >
          {complete ? <Tick /> : <Padlock />}
        </span>
      ) : null}
    </div>
  )
}

/* Quest. Every value comes from a token; nothing here is a literal colour,
   size, duration or typeface.

   The progress row is a segments or a progress-bar and styles itself. What is
   here is the card around it, the title, the reward pill and the two states. */

.gs-quest {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: var(--gs-space-2) var(--gs-space-3);

  padding: var(--gs-space-4);

  color: var(--gs-color-ink);
  background: var(--gs-color-surface-raised);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-lg);
  box-shadow: var(--gs-depth-raised);
}

.gs-quest__title {
  grid-column: 1;
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
}

/* The "+500" pill. Raised rather than flat, because it is the thing on offer
   and the depth rule says an object the player is being offered sits above the
   surface it sits on. */
.gs-quest__reward {
  grid-column: 2;
  justify-self: end;

  padding: var(--gs-space-1) var(--gs-space-3);

  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-type-stat-font-size);
  font-weight: var(--gs-type-stat-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  line-height: 1;

  color: var(--gs-color-on-bright);
  background: var(--gs-color-reward);
  border: var(--gs-stroke-control, var(--gs-stroke-hairline)) solid var(--gs-color-reward-base);
  border-radius: var(--gs-radius-full);
  box-shadow: var(--gs-depth-reward);
}

.gs-quest__detail {
  grid-column: 1 / -1;
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  line-height: var(--gs-type-body-line-height);
  color: var(--gs-color-ink-secondary);
}

.gs-quest__progress {
  grid-column: 1 / -1;
  min-width: 0;
}

.gs-quest__glyph {
  grid-column: 2;
  grid-row: 1;
  justify-self: end;
  display: flex;
  line-height: 1;
  font-size: var(--gs-size-icon-utility);
  /* Emphasis, not motion: this duration survives reduced motion on purpose. */
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

/* -- complete ------------------------------------------------------------- */
/* Three channels: the card's edge, the tick above, and the nested progress
   component's own completion, which it carries itself. */
.gs-quest[data-gs-complete='true'] {
  border-color: var(--gs-color-positive-base);
}

.gs-quest[data-gs-complete='true'] .gs-quest__glyph {
  color: var(--gs-color-positive);
}

/* -- locked --------------------------------------------------------------- */
/* Keeps its shape and shows a padlock, the same distinction button draws
   between "not yet" and "not ever". The dashed edge is the third channel. */
.gs-quest[data-gs-locked='true'] {
  border-style: dashed;
  color: var(--gs-color-ink-secondary);
}

.gs-quest[data-gs-locked='true'] .gs-quest__glyph {
  color: var(--gs-color-ink-secondary);
}
